import{af as o,ad as r,z as i,J as s,ab as t,x as n}from"./chunks/framework.D-2fLa7v.js";const m=JSON.parse('{"title":"GPS and GSM status LEDs","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/capabilities/gps-gsm-status-leds.md","filePath":"devices/capabilities/gps-gsm-status-leds.md"}'),d={name:"devices/capabilities/gps-gsm-status-leds.md"};function c(l,e,h,p,u,f){const a=r("CapabilityDevices");return i(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794240761000"},[e[0]||(e[0]=t('<h1 id="gps-and-gsm-status-leds" tabindex="-1">GPS and GSM status LEDs <a class="header-anchor" href="#gps-and-gsm-status-leds" aria-label="Permalink to &quot;GPS and GSM status LEDs&quot;">​</a></h1><p>Some older trackers have two diagnostic indicators: one for GPS and one for the mobile network, often labelled GSM. These are separate from the <a href="/docs/pr/40/devices/capabilities/four-power-leds">four power LEDs</a>.</p><p>The pair describes receiver and connection state, not a general fault code. It is not present on Pro3 or ZE3, and is not the <a href="/docs/pr/40/devices/capabilities/rgb-status-leds">RGB status LED capability</a> used by RH2.</p><h2 id="diagnostic-display" tabindex="-1">Diagnostic display <a class="header-anchor" href="#diagnostic-display" aria-label="Permalink to &quot;Diagnostic display&quot;">​</a></h2><p>Use the model/revision notes below to identify the <strong>secondary diagnostic colour</strong>. It is not universally green. Both channels can be on together; this does not establish a third, universal mixed colour.</p><table tabindex="0"><thead><tr><th>Mobile-network indicator</th><th>What the standard display can mean</th></tr></thead><tbody><tr><td>Red only</td><td>Flight mode is enabled, or signal strength is zero/unknown while the connection is not open</td></tr><tr><td>Red and secondary colour together</td><td>One signal bar is reported and the connection is not open, with flight mode off</td></tr><tr><td>Secondary colour only</td><td>At least two signal bars are reported or the connection is open, with flight mode off</td></tr></tbody></table><p>The mobile indicator is not confirmation that data reached the server. Check the latest successful communication in the app or portal.</p><table tabindex="0"><thead><tr><th>GPS indicator while the receiver is awake</th><th>What the standard display can mean</th></tr></thead><tbody><tr><td>Red only</td><td>No fix yet, before the waiting-for-fix stage</td></tr><tr><td>Red and secondary colour together</td><td>Waiting for a fix, without a lock yet</td></tr><tr><td>Secondary colour only</td><td>A fix is available, or the receiver has moved beyond the waiting-for-fix stage</td></tr></tbody></table><p>When GPS is asleep, its indicator can reflect whether the <strong>previous</strong> fix attempt failed rather than whether there is a live fix now. A secondary-colour light alone is therefore not a guarantee of a current accurate location. Check the location timestamp and accuracy in the app or portal.</p><h2 id="devices-and-colour-variants" tabindex="-1">Devices and colour variants <a class="header-anchor" href="#devices-and-colour-variants" aria-label="Permalink to &quot;Devices and colour variants&quot;">​</a></h2>',10)),n(a,{capability:"gps-gsm-status-leds"}),e[1]||(e[1]=t('<h3 id="pro-pr2" tabindex="-1">Pro PR2 <a class="header-anchor" href="#pro-pr2" aria-label="Permalink to &quot;Pro PR2 {#pro-pr2}&quot;">​</a></h3><p><a href="/docs/pr/40/devices/history/PR2">ProN/PR2</a>, device ID prefix 20, has four battery indicators and the separate GPS/GSM pair. PR2 designs use red with amber or yellow depending on the board revision. Its <a href="/docs/pr/40/devices/history/PR2#two-red-lights-and-four-orange-lights-after-a-restart">two-red/four-orange startup example</a> belongs to this model, not Pro3.</p><h3 id="zero-ze2" tabindex="-1">Zero ZE2 <a class="header-anchor" href="#zero-ze2" aria-label="Permalink to &quot;Zero ZE2 {#zero-ze2}&quot;">​</a></h3><p><a href="/docs/pr/40/devices/zero/">ZeroN/ZE2</a>, prefix 19, uses the same diagnostic logic. Revision 05 uses yellow and red diagnostic LEDs. A firmware channel named G does not establish that the physical light is green. Use the icons on the case to identify the indicators. ZE3 does not have this pair.</p><h3 id="enviro-en2" tabindex="-1">Enviro EN2 <a class="header-anchor" href="#enviro-en2" aria-label="Permalink to &quot;Enviro EN2 {#enviro-en2}&quot;">​</a></h3><p><a href="/docs/pr/40/devices/enviro/">EnviroN/EN2</a>, prefix 26, uses the shared diagnostic logic. Its exact diagnostic colours must be checked against the supplied board revision. Do not infer a colour chart from another six-indicator model; ask support if the colours differ from the supplied instructions.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>Both colour channels can be lit together. Their appearance depends on the components and case, so there is no universal third mixed colour. Startup, alarms and application control can override the ordinary diagnostic display. Use the <a href="/docs/pr/40/guides/leds">LED guide</a> to put a pattern in context.</p>',8))])}const b=o(d,[["render",c]]);export{m as __pageData,b as default};
